    private void ResetSpecialized() { _disciplineWorkspace = null; _disciplineSnapshots.Clear(); _fieldsGrid.Rows.Clear(); _rulesGrid.Rows.Clear(); _disciplineEditorDirty = false; ResetElectrical(); }
    private void SelectSpecializedSource() { _disciplineWorkspace = null; _fieldsGrid.Rows.Clear(); _rulesGrid.Rows.Clear(); _selectedSourceRowId = null; _disciplineEditorDirty = false; }
    private void LoadSpecializedState(JsonNode value) { foreach (var (key, item) in value["disciplineSnapshots"]?.AsObject() ?? new JsonObject()) if (item is JsonObject saved) _disciplineSnapshots[key] = (JsonObject)saved.DeepClone(); LoadElectrical(value); }
    private void SaveSpecializedState(JsonObject value) { if (_disciplineWorkspace is JsonObject workspace) _disciplineSnapshots[DisciplineKey] = (JsonObject)workspace.DeepClone(); value["disciplineSnapshots"] = System.Text.Json.JsonSerializer.SerializeToNode(_disciplineSnapshots); SaveElectrical(value); }
    public async Task<JsonNode> DisciplineAction(string action, JsonObject? payload = null, string? filled = null)
    {
        await AuthorizeProfile(true, Token);
        if (_bundle == null || _current == null) throw new InvalidOperationException(); var context = new JsonObject { ["workspace"] = _disciplineWorkspace?.DeepClone(), ["payload"] = payload ?? new JsonObject() }; var file = Path.Combine(_projectRoot, "discipline-" + Guid.NewGuid().ToString("N") + ".json"); await Atomic(file, context.ToJsonString(), Token); var command = Command("discipline", file, filled) with { Parameters = new() { ["filename"] = _current.Filename, ["action"] = action, ["discipline"] = _discipline.SelectedItem?.ToString() ?? "electrical" } }; var result = await Execute(command); _disciplineWorkspace = result["workspace"]!.DeepClone(); ShowDiscipline(result); _dirty = true; return result;
    }
    private void ShowDiscipline(JsonNode result)
    {
        _bindingDiscipline = true;
        _fieldsGrid.Rows.Clear(); foreach (var field in _disciplineWorkspace!["fields"]!.AsArray()) { var id = field!["id"]!.GetValue<string>(); var index = _fieldsGrid.Rows.Add(id, field["label"]?.GetValue<string>() ?? "", field["type"]?.GetValue<string>() ?? "text", field["unit"]?.GetValue<string>() ?? "", field["required"]?.GetValue<bool>() ?? false, _disciplineWorkspace["values"]?[id]?.ToString() ?? "", field["valueSource"]?.GetValue<string>() ?? "input", field["outputPattern"]?.GetValue<string>() ?? "{value}"); _fieldsGrid.Rows[index].Tag = field.DeepClone(); }
        _rulesGrid.Rows.Clear(); foreach (var rule in _disciplineWorkspace["rules"]!.AsArray()) _rulesGrid.Rows.Add(rule!["id"]!.GetValue<string>(), rule["label"]?.GetValue<string>() ?? "", rule["operation"]?.GetValue<string>() ?? "mean", string.Join(";", rule["fieldIds"]?.AsArray().Select(id => id!.GetValue<string>()) ?? []), rule["unit"]?.GetValue<string>() ?? "", rule["criterion"]?["min"]?.ToString() ?? "", rule["criterion"]?["max"]?.ToString() ?? "", rule["criterion"]?["source"]?.ToString() ?? "", rule["criterion"]?["confirmed"]?.GetValue<bool>() ?? false, rule["narratives"]?["inside"]?.ToString() ?? "", rule["narratives"]?["outside"]?.ToString() ?? "", rule["narratives"]?["recommendation"]?.ToString() ?? "");
        _diagnosisNotes.Text = _disciplineWorkspace["notes"]?["diagnosis"]?.ToString() ?? ""; _conclusionNotes.Text = _disciplineWorkspace["notes"]?["conclusion"]?.ToString() ?? ""; _improvementNotes.Text = _disciplineWorkspace["notes"]?["improvements"]?.ToString() ?? "";
        _calculationResult.Text = "선택 입력 양식·계산 결과 · 회사 보고서 승인 아님\n" + result["validation"]?.ToJsonString(DisplayJson) + "\n" + result["results"]?.ToJsonString(DisplayJson); _bindingDiscipline = false; _disciplineEditorDirty = false; Status("명시적으로 입력한 값만 계산합니다. 미입력·기준 미확인·0 나눗셈은 보류합니다.");
    }
    private JsonNode SelectedReportRow() => AnalysisRows().FirstOrDefault(row => row["id"]?.GetValue<string>() == _selectedSourceRowId) ?? throw new InvalidOperationException();
    private async Task AddSelectedDisciplineCellAsync() { var row = SelectedReportRow(); await DisciplineAction("addCellField", new JsonObject { ["tableId"] = row["target"]?["tableId"]?.DeepClone(), ["cellId"] = row["target"]?["cellId"]?.DeepClone() }); }
    private async Task AddSelectedDisciplineTableAsync() { var row = SelectedReportRow(); await AddDisciplineTableFieldsAsync(row["target"]!["tableId"]!.GetValue<string>()); }
    public Task<JsonNode> AddDisciplineTableFieldsAsync(string tableId) => DisciplineAction("addTableFields", new JsonObject { ["tableId"] = tableId, ["headerRows"] = 1, ["labelColumns"] = 1 });
    private async Task RestoreDisciplineAsync() { if (_current == null || !_disciplineSnapshots.TryGetValue(DisciplineKey, out var saved)) throw new InvalidOperationException(); _disciplineWorkspace = saved.DeepClone(); _disciplineWorkspace["confirmedRevision"] = null; await DisciplineAction("inspect"); Status("같은 원본·분야의 저장 입력을 검토용으로 불러왔습니다. 새 회차는 값을 비우고 현재 자료로 재확인하세요."); }
    public async Task SaveDisciplineEditorAsync() { await UpdateDisciplineEditorAsync(); await SaveAsync(Token); }
    private async Task UpdateDisciplineEditorAsync()
    {
        _fieldsGrid.EndEdit(); _rulesGrid.EndEdit(); var fields = new JsonArray(); var values = new JsonObject(); foreach (DataGridViewRow row in _fieldsGrid.Rows) { var field = (JsonObject)((JsonNode)row.Tag!).DeepClone(); var id = field["id"]!.GetValue<string>(); field["label"] = Convert.ToString(row.Cells["label"].Value) ?? ""; field["type"] = Convert.ToString(row.Cells["type"].Value) ?? "text"; field["unit"] = Convert.ToString(row.Cells["unit"].Value) ?? ""; field["required"] = row.Cells["required"].Value is true; field["valueSource"] = Convert.ToString(row.Cells["valueSource"].Value) ?? "input"; field["outputPattern"] = Convert.ToString(row.Cells["outputPattern"].Value) ?? "{value}"; fields.Add(field); values[id] = Convert.ToString(row.Cells["value"].Value) ?? ""; }
        var rules = new JsonArray(); foreach (DataGridViewRow row in _rulesGrid.Rows) { string Cell(string key) => Convert.ToString(row.Cells[key].Value) ?? ""; var rule = new JsonObject { ["id"] = Cell("id"), ["label"] = Cell("label"), ["operation"] = Cell("operation"), ["fieldIds"] = new JsonArray(Cell("fieldIds").Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Select(value => (JsonNode?)JsonValue.Create(value)).ToArray()), ["unit"] = Cell("unit"), ["narratives"] = new JsonObject { ["inside"] = Cell("inside"), ["outside"] = Cell("outside"), ["recommendation"] = Cell("recommendation") } }; if (Cell("min") != "" || Cell("max") != "" || Cell("source") != "") rule["criterion"] = new JsonObject { ["min"] = Cell("min"), ["max"] = Cell("max"), ["source"] = Cell("source"), ["confirmed"] = row.Cells["confirmed"].Value is true }; rules.Add(rule); }
        await DisciplineAction("replaceEditor", new JsonObject { ["fields"] = fields, ["rules"] = rules, ["values"] = values, ["notes"] = new JsonObject { ["diagnosis"] = _diagnosisNotes.Text, ["conclusion"] = _conclusionNotes.Text, ["improvements"] = _improvementNotes.Text } });
    }
    public async Task ConfirmDisciplineAsync() { await SaveDisciplineEditorAsync(); await DisciplineAction("confirmSchema"); await SaveAsync(Token); }
    private async Task EvaluateDisciplineAsync() { await SaveDisciplineEditorAsync(); var value = await DisciplineAction("inspect"); _calculationResult.Text = value["validation"]?.ToJsonString(DisplayJson) + "\n" + value["results"]?.ToJsonString(DisplayJson); }
    private async Task AddRuleFromSelectedAsync() { if (_disciplineWorkspace == null) throw new InvalidOperationException(); var ids = _fieldsGrid.SelectedRows.Cast<DataGridViewRow>().OrderBy(row => row.Index).Where(row => Convert.ToString(row.Cells["type"].Value) == "number").Select(row => Convert.ToString(row.Cells["id"].Value)!).ToArray(); if (ids.Length == 0 || string.IsNullOrWhiteSpace(_ruleLabel.Text)) throw new InvalidOperationException(); await SaveDisciplineEditorAsync(); await DisciplineAction("setRule", new JsonObject { ["rule"] = new JsonObject { ["id"] = Guid.NewGuid().ToString("N"), ["label"] = _ruleLabel.Text, ["operation"] = _operation.SelectedItem?.ToString() ?? "mean", ["fieldIds"] = new JsonArray(ids.Select(value => (JsonNode?)JsonValue.Create(value)).ToArray()), ["unit"] = "" } }); }
    private void RemoveSelectedRules() { foreach (var row in _rulesGrid.SelectedRows.Cast<DataGridViewRow>().OrderByDescending(row => row.Index).ToArray()) _rulesGrid.Rows.Remove(row); _dirty = true; }
    private async Task RemoveDisciplineFieldsAsync() { foreach (var row in _fieldsGrid.SelectedRows.Cast<DataGridViewRow>().OrderByDescending(row => row.Index).ToArray()) _fieldsGrid.Rows.Remove(row); _dirty = _disciplineEditorDirty = true; await SaveDisciplineEditorAsync(); }
    private async Task ExportDisciplineCollection() { using var dialog = new SaveFileDialog { Filter = "선택칸 조사 JSON|*.json", FileName = "선택칸-조사.json" }; if (dialog.ShowDialog(this) == DialogResult.OK) await ExportDisciplineCollectionToAsync(dialog.FileName); }
    public async Task ExportDisciplineCollectionToAsync(string destination) { ExportDestination(destination); var value = await DisciplineAction("exportCollection"); await ExportNewBytes(destination, System.Text.Encoding.UTF8.GetBytes(value["collection"]!.ToJsonString()), Token); }
    private async Task ImportDisciplineCollection() { using var dialog = new OpenFileDialog { Filter = "선택칸 조사 JSON|*.json" }; if (dialog.ShowDialog(this) == DialogResult.OK) await ImportDisciplineCollectionFromAsync(dialog.FileName); }
    public async Task ImportDisciplineCollectionFromAsync(string source) { await DisciplineAction("importCollection", filled: source); var asset = await _services.Assets.ImportAsync(_services.Actor, Context.ProjectId!, source, Token); if (_materials.All(item => item.Id != asset.Id)) _materials.Add(new EvidenceItem(asset.Id, Path.GetFileName(source), asset.StoredPath, asset.Sha256)); RefreshEvidence(); await SaveAsync(Token); }
